      throw new Error('invalid payment');
    }

    let receipt: Receipt | undefined;
    for (let n = 0; n < attempts; n++) {
      try {
        if (receipt === undefined) {
          // Debit at most once: Ledger dedupes by tenant+key, so replaying after a
          // transient pre-commit failure still yields the original receipt.
          receipt = await this.ledger.apply(tenant, key, cents);
