        // The debit is committed; acknowledgement is external and may throw
        // Transient. Forward the same committed receipt on every attempt.
        await this.transport.acknowledge(receipt);
        return receipt;
      } catch (error) {
        if (!(error instanceof Transient) || n === attempts - 1) throw error;
      }
    }
    throw new Error('invalid payment'); // Unreachable: validation guarantees attempts >= 1.
  }
}
```

