```ts
import { Ledger, Receipt } from './ledger';
import { Transient, Transport } from './transport';

export class PaymentService {
  constructor(private readonly ledger: Ledger, private readonly transport: Transport) {}

  /** Pay `cents` under `tenant`/`key` and acknowledge the committed receipt. */
  async pay(tenant: string, key: string, cents: number, attempts = 3): Promise<Receipt> {
    // Validate everything up front: no ledger write and no transport call may
    // happen for rejected input.
    if (!isValidTenantOrKey(tenant) || !isValidTenantOrKey(key) || !isPositiveInteger(cents) || !isValidAttempts(attempts)) {
      throw new Error('invalid payment');
    }

    // The committed receipt. Acquired once; every acknowledgement attempt
    // forwards this same object so a retried ack can never describe a second
    // debit.
    let receipt: Receipt | undefined;

    for (let n = 0; n < attempts; n++) {
      try {
        if (receipt === undefined) {
          // Ledger.apply is idempotent per tenant+key: this debits at most once,
          // returns the original receipt for an equal-amount replay, and throws
          // 'key conflict' when the tenant/key is reused with another amount.
          receipt = await this.ledger.apply(tenant, key, cents);
        }

        // The debit is committed; acknowledgement is external and may throw
        // Transient. Forward the same committed receipt on every attempt.
        await this.transport.acknowledge(receipt);
        return receipt;
      } catch (error) {
        // Retry only Transient, up to `attempts` total tries; otherwise fail
        // fast, rethrowing the original error on the last attempt.
        if (!(error instanceof Transient) || n === attempts - 1) throw error;
      }
    }

    // Unreachable: attempts >= 1, so the first iteration returns or throws.
    throw new Error('invalid payment');
  }
}

function isValidTenantOrKey(value: string): boolean {
  return typeof value === 'string' && value.length > 0;
}

function isPositiveInteger(value: number): boolean {
  return Number.isInteger(value) && value > 0;
}

function isValidAttempts(value: number): boolean {
  return Number.isInteger(value) && value >= 1 && value <= 5;
}
```

