```ts
export interface Receipt { id: number; tenant: string; key: string; cents: number }

export class Ledger {
  readonly entries: Receipt[] = [];

  /** tenant -> key -> first receipt committed for that tenant/key. */
  private readonly index = new Map<string, Map<string, Receipt>>();

  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    const amount = cents;

    // Replay / conflict detection. The body contains no await, so this
    // check-and-commit sequence is atomic with respect to other apply() calls:
    // concurrent invocations are effectively serialized in call order.
    const existing = this.index.get(tenant)?.get(key);
    if (existing !== undefined) {
      if (existing.cents === cents) return existing; // equal-amount replay: original receipt, no new debit
      throw new Error('key conflict'); // tenant/key reused with another amount: fail without debiting
    }

    const receipt = { id: this.entries.length + 1, tenant, key, cents: amount };
    this.entries.push(receipt);

    let byKey = this.index.get(tenant);
    if (byKey === undefined) {
      byKey = new Map<string, Receipt>();
      this.index.set(tenant, byKey);
    }
    byKey.set(key, receipt);

    return receipt;
  }
}
```

